<?php
namespace Modules\Finance\Services;
use Carbon\Carbon;use Illuminate\Support\Facades\DB;use Modules\Core\Models\User;use Modules\Core\Services\AuditService;use Modules\Finance\Models\ApPayment;use Modules\Finance\Models\ArPayment;use Modules\Finance\Models\BankAccount;use Modules\Finance\Models\BankReconciliationMatch;use Modules\Finance\Models\BankStatementImport;use Modules\Finance\Models\BankStatementLine;use RuntimeException;
class BankReconciliationService
{
 public function __construct(private GlPostingService$gl,private AuditService$audit){}
 public function import(BankAccount$a,array$h,array$rows,User$u):BankStatementImport{$this->access($u,(int)$a->company_id);if(!$a->is_active)throw new RuntimeException('Bank account tidak aktif.');if($rows===[]||count($rows)>5000)throw new RuntimeException('Statement wajib berisi 1–5000 baris.');$start=Carbon::createFromFormat('Y-m-d',$h['period_start']);$end=Carbon::createFromFormat('Y-m-d',$h['period_end']);if($end->lt($start))throw new RuntimeException('Period end tidak boleh sebelum period start.');$normalized=[];$credits=0.;$debits=0.;foreach(array_values($rows)as$i=>$r){$date=Carbon::createFromFormat('Y-m-d',$r['transaction_date']);if($date->lt($start)||$date->gt($end))throw new RuntimeException('Tanggal line harus berada dalam period statement.');$dir=strtoupper($r['direction']);$amount=round((float)$r['amount'],4);if(!in_array($dir,['DEBIT','CREDIT'],true)||$amount<=0)throw new RuntimeException('Direction/amount statement line tidak valid.');$canonical=[$a->id,$date->toDateString(),$r['value_date']??null,$dir,$amount,trim((string)($r['reference_no']??'')),trim((string)($r['description']??''))];$fingerprint=hash('sha256',json_encode($canonical,JSON_PRESERVE_ZERO_FRACTION|JSON_THROW_ON_ERROR));$normalized[]=['line_no'=>$i+1,'transaction_date'=>$date->toDateString(),'value_date'=>$r['value_date']??null,'direction'=>$dir,'amount'=>$amount,'reference_no'=>$r['reference_no']??null,'description'=>$r['description']??null,'fingerprint'=>$fingerprint];$dir==='CREDIT'?$credits+=$amount:$debits+=$amount;}$expected=round((float)$h['opening_balance']+$credits-$debits,4);if(abs($expected-(float)$h['closing_balance'])>.0001)throw new RuntimeException("Statement tidak balance: expected closing {$expected}.");$contentHash=hash('sha256',json_encode([$a->id,$h['statement_no'],$h['period_start'],$h['period_end'],$h['opening_balance'],$h['closing_balance'],$normalized],JSON_PRESERVE_ZERO_FRACTION|JSON_THROW_ON_ERROR));return DB::transaction(function()use($a,$h,$normalized,$contentHash,$u){DB::table('bank_accounts')->where('id',$a->id)->lockForUpdate()->firstOrFail();foreach($normalized as$r)if(BankStatementLine::where('bank_account_id',$a->id)->where('fingerprint',$r['fingerprint'])->exists())throw new RuntimeException("Duplicate bank transaction fingerprint pada line {$r['line_no']}.");$s=BankStatementImport::create(['company_id'=>$a->company_id,'bank_account_id'=>$a->id,'statement_no'=>$h['statement_no'],'period_start'=>$h['period_start'],'period_end'=>$h['period_end'],'opening_balance'=>$h['opening_balance'],'closing_balance'=>$h['closing_balance'],'row_count'=>count($normalized),'content_hash'=>$contentHash,'status'=>'IMPORTED','imported_by'=>$u->id]);foreach($normalized as$r)$s->lines()->create($r+['bank_account_id'=>$a->id]);$this->audit->record('create',$s,after:['statement_no'=>$s->statement_no,'row_count'=>$s->row_count,'content_hash'=>$contentHash]);return$s->load('lines');});}
 public function match(BankStatementLine$line,string$type,int$id,float$amount,User$u):BankStatementLine{return DB::transaction(function()use($line,$type,$id,$amount,$u){$l=BankStatementLine::whereKey($line->id)->lockForUpdate()->firstOrFail();$s=BankStatementImport::withoutGlobalScopes()->whereKey($l->bank_statement_import_id)->lockForUpdate()->firstOrFail();$this->access($u,(int)$s->company_id);if($s->status!=='IMPORTED'||$l->status==='IGNORED')throw new RuntimeException('Statement/line sudah terkunci.');if(!in_array($type,['AR_PAYMENT','AP_PAYMENT'],true))throw new RuntimeException('Source match tidak valid.');$p=$type==='AR_PAYMENT'?ArPayment::withoutGlobalScopes()->whereKey($id)->lockForUpdate()->first():ApPayment::withoutGlobalScopes()->whereKey($id)->lockForUpdate()->first();if(!$p||(int)$p->company_id!==(int)$s->company_id)throw new RuntimeException('Payment tidak ditemukan pada company statement.');$expected=$type==='AR_PAYMENT'?'CREDIT':'DEBIT';if($l->direction!==$expected)throw new RuntimeException('Direction statement tidak sesuai tipe payment.');$a=BankAccount::withoutGlobalScopes()->whereKey($s->bank_account_id)->firstOrFail();if((int)($a->currency_id??0)!==(int)($p->currency_id??0))throw new RuntimeException('Currency bank account dan payment harus sama.');$sourceTotal=$p->currency_id?(float)$p->amount:((float)$p->base_amount>0?(float)$p->base_amount:(float)$p->amount);$used=(float)BankReconciliationMatch::where('source_type',$type)->where('source_id',$id)->lockForUpdate()->sum('amount');$lineRemaining=(float)$l->amount-(float)$l->matched_amount;$sourceRemaining=$sourceTotal-$used;$amount=round($amount,4);if($amount<=0||$amount>$lineRemaining+.0001||$amount>$sourceRemaining+.0001)throw new RuntimeException('Match amount melebihi sisa line atau payment.');BankReconciliationMatch::create(['bank_statement_line_id'=>$l->id,'source_type'=>$type,'source_id'=>$id,'amount'=>$amount,'created_by'=>$u->id]);$matched=round((float)$l->matched_amount+$amount,4);$l->update(['matched_amount'=>$matched,'status'=>$matched>=(float)$l->amount-.0001?'MATCHED':'PARTIAL']);$this->audit->record('update',$l,after:['source_type'=>$type,'source_id'=>$id,'matched_amount'=>$matched]);return$l->fresh('matches');});}
 public function ignore(BankStatementLine$line,string$reason,User$u):BankStatementLine{return DB::transaction(function()use($line,$reason,$u){$l=BankStatementLine::whereKey($line->id)->lockForUpdate()->firstOrFail();$s=BankStatementImport::withoutGlobalScopes()->whereKey($l->bank_statement_import_id)->lockForUpdate()->firstOrFail();$this->access($u,(int)$s->company_id);if($s->status!=='IMPORTED'||$l->status!=='UNMATCHED'||trim($reason)==='')throw new RuntimeException('Hanya line UNMATCHED dapat di-ignore dengan alasan.');$l->update(['status'=>'IGNORED','ignore_reason'=>trim($reason)]);$this->audit->record('update',$l,after:['status'=>'IGNORED','reason'=>$reason]);return$l->fresh();});}
 public function bankFee(BankStatementLine$line,float$amount,User$u):BankStatementLine{return DB::transaction(function()use($line,$amount,$u){$l=BankStatementLine::whereKey($line->id)->lockForUpdate()->firstOrFail();$s=BankStatementImport::withoutGlobalScopes()->whereKey($l->bank_statement_import_id)->lockForUpdate()->firstOrFail();$this->access($u,(int)$s->company_id);if($s->status!=='IMPORTED'||$l->direction!=='DEBIT')throw new RuntimeException('Bank fee hanya untuk debit line pada statement terbuka.');$remaining=(float)$l->amount-(float)$l->matched_amount;$amount=round($amount,4);if($amount<=0||$amount>$remaining+.0001)throw new RuntimeException('Bank fee melebihi sisa line.');$j=$this->gl->postEvent($s->company_id,'BANK_FEE','bank_statement_lines',$l->id,$amount,$l->transaction_date->format('Y-m'),$u,"Bank fee statement {$s->statement_no}",$l->transaction_date->toDateString())['journal'];BankReconciliationMatch::create(['bank_statement_line_id'=>$l->id,'source_type'=>'BANK_FEE','source_id'=>$j->id,'amount'=>$amount,'created_by'=>$u->id]);$matched=round((float)$l->matched_amount+$amount,4);$l->update(['matched_amount'=>$matched,'status'=>$matched>=(float)$l->amount-.0001?'MATCHED':'PARTIAL']);return$l->fresh('matches');});}
 public function reconcile(BankStatementImport$s,User$u):BankStatementImport{return DB::transaction(function()use($s,$u){$x=BankStatementImport::withoutGlobalScopes()->with('lines')->whereKey($s->id)->lockForUpdate()->firstOrFail();$this->access($u,(int)$x->company_id);if($x->status==='RECONCILED')return$x;if($x->lines->contains(fn($l)=>!in_array($l->status,['MATCHED','IGNORED'],true)))throw new RuntimeException('Semua statement line harus MATCHED atau IGNORED.');$x->update(['status'=>'RECONCILED','reconciled_at'=>now(),'reconciled_by'=>$u->id]);$this->audit->record('approve',$x,after:['status'=>'RECONCILED','line_count'=>$x->row_count]);return$x->fresh('lines.matches');});}
 private function access(User$u,int$c):void{if((int)$u->company_id!==$c&&!$u->companies()->whereKey($c)->exists())throw new RuntimeException('User tidak memiliki akses ke company bank account.');}
}
